const cmds = [
  ["i2018-files", "for f in .archon-horizon/inbox/local/items/I-2018.yaml .archon-horizon/inbox/local/history/I-2018.jsonl .archon-horizon/inbox/local/comments/I-2018/C-0001.md .archon-horizon/inbox/local/comments/I-2018/C-0002.md; do echo ==== $f; sed -n '1,220p' \"$f\"; done"],
  ["i2018-head", "for f in .archon-horizon/inbox/local/items/I-2018.yaml .archon-horizon/inbox/local/history/I-2018.jsonl .archon-horizon/inbox/local/comments/I-2018/C-0001.md .archon-horizon/inbox/local/comments/I-2018/C-0002.md; do \"$HORIZON_GIT\" show HEAD:\"$f\" >/tmp/x 2>/dev/null && echo ====HEAD:$f && sed -n '1,30p' /tmp/x; done"],
  ["unread", "\"$HORIZON_BIN\" inbox list --mine --unread --kind conversation --json | jq '{attention,items}'"],
  ["scope", "\"$HORIZON_GIT\" diff --name-status HEAD -- .archon-horizon/inbox/local/items/I-2018.yaml .archon-horizon/inbox/local/history/I-2018.jsonl .archon-horizon/inbox/local/comments/I-2018 .archon-horizon/tasks/items/ajcr-blueprint-reconcile.yaml .archon-horizon/tasks/comments/ajcr-blueprint-reconcile MainProjects/Algebraic-Jacobian-Challenge-Rebuild/blueprint/src/chapters/DivisorScheme.tex"],
  ["cached-scope", "\"$HORIZON_GIT\" diff --cached --name-status HEAD -- .archon-horizon/inbox/local/items/I-2018.yaml .archon-horizon/inbox/local/history/I-2018.jsonl .archon-horizon/inbox/local/comments/I-2018 .archon-horizon/tasks/items/ajcr-blueprint-reconcile.yaml .archon-horizon/tasks/comments/ajcr-blueprint-reconcile MainProjects/Algebraic-Jacobian-Challenge-Rebuild/blueprint/src/chapters/DivisorScheme.tex"],
  ["head-check", "\"$HORIZON_GIT\" diff-tree --check HEAD^ HEAD 2>&1 | wc -l"],
  ["advisories", "\"$HORIZON_BIN\" inbox list --mine --status open --kind issue --json --limit 100 --comments 1 | jq '[.items[]|{id,title:(.body|split(\"\\n\")[0]),updated_at}]'"]
];
const out = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:25000});
  return `===== ${name} =====\n${r.output}`;
}));
text(out.join("\n"));

